def _usage_overall(raw):
    """
    Parse usage/overall.
    """
    usage = {}
    for line in raw.split('\n'):
        if line.startswith('Usage'):
            usage['Usage'] = line[len('Usage'):].strip()
        elif line.startswith('Total'):
            usage['Total'] = line[len('Total'):].strip()
        elif line.startswith('Used'):
            usage['Used'] = line[len('Used'):].strip()
        elif line.startswith('Free'):
            usage['Free'] = line[len('Free'):].strip()
        elif line.startswith('Shared'):
            usage['Shared'] = line[len('Shared'):].strip()
        elif line.startswith('Buffers'):
            usage['Buffers'] = line[len('Buffers'):].strip()
        elif line.startswith('Cached'):
            usage['Cached'] = line[len('Cached'):].strip()
        elif line.startswith('SwapCached'):
            usage['SwapCached'] = line[len('SwapCached'):].strip()
        elif line.startswith('Active'):
            usage['Active'] = line[len('Active'):].strip()
        elif line.startswith('Inactive'):
            usage['Inactive'] = line[len('Inactive'):].strip()
        elif line.startswith('Active(anon)'):
            usage['Active(anon)'] = line[len('Active(anon)'):].strip()
        elif line.startswith('Inactive(anon)'):
            usage['Inactive(anon)'] = line[len('Inactive(anon)'):].strip()
        elif line.startswith('Active(file)'):
